"""Lab 2: a table format in miniature. Data lives in immutable Parquet files; a transaction log of numbered JSON
commits says which files make up each version. That log is what gives a lake ACID tables and time travel."""

import json
import os
import shutil
import uuid
from pathlib import Path

import duckdb
import pandas as pd


class CommitConflict(Exception):
    pass


class MiniTable:
    def __init__(self, path):
        self.path = Path(path)
        self.log = self.path / "_log"
        self.log.mkdir(parents=True, exist_ok=True)
        self.con = duckdb.connect()

    # ---------------------------------------------------------------- the log
    def version(self):
        commits = sorted(self.log.glob("*.json"))
        return int(commits[-1].stem) if commits else -1

    def commit(self, actions, read_version, operation):
        """Atomically claim the next version number. Opening with O_CREAT | O_EXCL fails if another writer
        already created that file, which is how concurrent writers are detected (optimistic concurrency)."""
        target = self.log / f"{read_version + 1:020d}.json"
        # TODO: open target with os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL); if it raises
        #       FileExistsError, raise CommitConflict(f"version {read_version + 1} was committed by someone else").
        #       Then write {"operation": operation, "actions": actions} as JSON through os.fdopen(fd, "w").
        target.write_text(json.dumps({"operation": operation, "actions": actions}))   # unsafe placeholder
        return read_version + 1

    def files(self, version=None):
        """Replay the log up to a version: the set of data files that make up that snapshot."""
        version = self.version() if version is None else version
        active = {}
        for n in range(version + 1):
            for action in json.loads((self.log / f"{n:020d}.json").read_text())["actions"]:
                if "add" in action:
                    active[action["add"]["path"]] = action["add"]
                else:
                    active.pop(action["remove"]["path"])
        return active

    def history(self):
        return [(n, json.loads((self.log / f"{n:020d}.json").read_text())["operation"])
                for n in range(self.version() + 1)]

    # ---------------------------------------------------------------- reading
    def read(self, version=None, where="TRUE"):
        files = self.files(version)
        if not files:
            return pd.DataFrame()
        paths = ", ".join(f"'{self.path / p}'" for p in sorted(files))
        return self.con.sql(f"SELECT * FROM read_parquet([{paths}]) WHERE {where}").df()

    def files_for_day(self, day):
        """Data skipping: use each file's min/max statistics from the log to avoid opening files that can't match."""
        files = self.files()
        keep = list(files)     # TODO: keep only files whose min_day <= day <= max_day
        return keep, len(files) - len(keep)

    # ---------------------------------------------------------------- writing
    def _write_file(self, df):
        name = f"part-{uuid.uuid4().hex[:12]}.parquet"
        self.con.sql("SELECT * FROM df").write_parquet(str(self.path / name))
        return {"add": {"path": name, "rows": len(df), "min_day": str(df["reading_date"].min()),
                        "max_day": str(df["reading_date"].max())}}

    def append(self, df, read_version=None):
        read_version = self.version() if read_version is None else read_version
        return self.commit([self._write_file(df)], read_version, "append")

    def delete(self, where):
        """Copy-on-write delete: rewrite each affected file without the deleted rows, then swap them in one commit."""
        read_version = self.version()
        actions = []
        for path in sorted(self.files(read_version)):
            df = self.con.sql(f"SELECT * FROM '{self.path / path}'").df()
            hit = self.con.sql(f"SELECT count(*) FROM df WHERE {where}").fetchone()[0]
            # TODO: if the file has matching rows, add a {"remove": {"path": path}} action, and, if any rows
            #       remain (SELECT * FROM df WHERE NOT (<where>)), write them to a new file with self._write_file()
        return self.commit(actions, read_version, f"delete where {where}")

    def optimize(self):
        """Compaction: replace many small files with one, without changing the rows."""
        read_version = self.version()
        files = self.files(read_version)
        everything = self.read(read_version)
        actions = [{"remove": {"path": p}} for p in sorted(files)] + [self._write_file(everything)]
        return self.commit(actions, read_version, f"optimize {len(files)} files into 1")

    def vacuum(self, keep_from_version):
        """Delete data files no version from keep_from_version onwards refers to. Time travel to older
        versions stops working, which is why vacuuming keeps a retention period."""
        needed = set()
        for v in range(keep_from_version, self.version() + 1):
            needed |= set(self.files(v))
        removed = [p for p in self.path.glob("part-*.parquet") if p.name not in needed]
        for p in removed:
            p.unlink()
        return len(removed)


def day_batch(day, turbines=("T1", "T2", "T3", "T4")):
    return pd.DataFrame({"turbine_id": list(turbines),
                         "reading_date": pd.to_datetime([day] * len(turbines)).date,
                         "vibration_mm_s": [{"T1": 3.1, "T2": 2.9, "T3": 3.0, "T4": 3.9}[t] for t in turbines]})


def main():
    shutil.rmtree("turbine_table", ignore_errors=True)
    table = MiniTable("turbine_table")
    for day in ["2025-06-01", "2025-06-02", "2025-06-03"]:
        v = table.append(day_batch(day))
        print(f"v{v}: appended {day}; {len(table.read())} rows in {len(table.files())} files")

    v = table.delete("turbine_id = 'T3' AND reading_date = DATE '2025-06-02'")
    print(f"v{v}: deleted one reading; {len(table.read())} rows now, {len(table.read(version=2))} rows at v2 (time travel)")

    keep, skipped = table.files_for_day("2025-06-03")
    print(f"Data skipping for 2025-06-03: read {len(keep)} file, skipped {skipped}")

    # two writers both start from the current version; the second to commit must notice
    start = table.version()
    first = table.append(day_batch("2025-06-04", ["T1", "T2"]), read_version=start)
    try:
        table.append(day_batch("2025-06-04", ["T3", "T4"]), read_version=start)
    except CommitConflict as e:
        print(f"Writer B: conflict ({e}); both were appends, so B rereads and retries")
        second = table.append(day_batch("2025-06-04", ["T3", "T4"]))
        print(f"v{first} by writer A, v{second} by writer B; {len(table.read())} rows")

    v = table.optimize()
    print(f"v{v}: {table.history()[-1][1]}; still {len(table.read())} rows")
    print(f"Vacuum keeping v{v} onwards: deleted {table.vacuum(v)} unreferenced files")
    print("History:", table.history())


if __name__ == "__main__":
    main()

